class Solution {
public:
    string stringShift(string s, vector<vector<int>>& shift) {
        int n = s.size();
        if (n == 0) {
            return s;
        }
        int right = 0;
        for (const auto& operation : shift) {
            right += operation[0] == 1 ? operation[1] : -operation[1];
            right %= n;
        }
        right = (right + n) % n;
        return s.substr(n - right) + s.substr(0, n - right);
    }
};
